Use `pg` (node-postgres) with `Pool`:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                  // max connections (default 10)
  min: 2,                   // keep alive floor
  // Timeouts (ms)
  connectionTimeoutMillis: 5000,   // fail fast if no connection available
  idleTimeoutMillis: 30000,        // release idle connections after 30s
  // Query-level timeout (postgres-side)
  statement_timeout: 10000,        // kill queries running > 10s
});

// Error handler — REQUIRED, unhandled 'error' kills process
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});

export async function query(text, params) {
  const start = Date.now();
  try {
    const res = await pool.query(text, params);
    return res;
  } catch (err) {
    // Rethrow with context
    err.query = text;
    throw err;
  } finally {
    // Optional: log slow queries
    const duration = Date.now() - start;
    if (duration > 1000) console.warn('Slow query', { text, duration });
  }
}

// For transactions — must use single client
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();  // ALWAYS release, even on error
  }
}

// Graceful shutdown
process.on('SIGTERM', () => pool.end());
```

Key points:

- `pool.on('error')` mandatory — missing it crashes process on idle client errors
- `client.release()` in `finally` — leak without it, pool exhausts
- `connectionTimeoutMillis` controls wait for available slot, not TCP connect
- `statement_timeout` is server-side; set at session level in `pool.connect()` for per-request control
- `max: 20` assumes Postgres default `max_connections=100`; leave headroom for other apps/tools
